pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC1155Probe {
    function balanceOf(address account, uint256 id) external view returns (uint256);
    function balanceOfBatch(address[] calldata accounts, uint256[] calldata ids) external view returns (uint256[] memory);
    function setApprovalForAll(address operator, bool approved) external;
    function isApprovedForAll(address account, address operator) external view returns (bool);
    function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes calldata data) external;
    function safeBatchTransferFrom(address from, address to, uint256[] calldata ids, uint256[] calldata amounts, bytes calldata data) external;
}

interface IERC1155MetadataURIProbe {
    function uri(uint256 id) external view returns (string memory);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // Structural ERC165 rule: since C supports IERC1155MetadataURI (its id is
        // supported), it must also support the base IERC1155 interface, whose id is
        // the MetadataURI id XOR the selector of the one extra member (uri).
        bytes4 baseId = type(IERC1155MetadataURIProbe).interfaceId ^ IERC1155MetadataURIProbe.uri.selector;
        bytes4 metadataId = type(IERC1155MetadataURIProbe).interfaceId;
        bytes4 erc165Id = type(IERC165).interfaceId;
        bytes4 probeId = type(IERC1155Probe).interfaceId ^ baseId ^ baseId; // keep probe referenced
        probeId = baseId ^ (interfaceId ^ interfaceId);
        bool expected =
            (probeId == erc165Id) ||
            (probeId == metadataId) ||
            (probeId == baseId);
        // Reference C advertises exactly the implemented interfaces for every id;
        // in particular the base IERC1155 id is always advertised, which the mutant denies.
        assertTrue((c.supportsInterface(probeId) == expected) && c.supportsInterface(baseId));
    }
}

