pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Selector-derived interface ids (no external interface imports needed)
    bytes4 constant ERC165_ID = type(uint32).max ^ bytes4(keccak256("supportsInterface(bytes4)"));
    bytes4 constant IERC1155_ID =
        bytes4(keccak256("balanceOf(address,uint256)")) ^
        bytes4(keccak256("balanceOfBatch(address[],uint256[])")) ^
        bytes4(keccak256("setApprovalForAll(address,bool)")) ^
        bytes4(keccak256("isApprovedForAll(address,address)")) ^
        bytes4(keccak256("safeTransferFrom(address,address,uint256,uint256,bytes)")) ^
        bytes4(keccak256("safeBatchTransferFrom(address,address,uint256[],uint256[],bytes)"));
    bytes4 constant IERC1155_METADATA_URI_ID =
        IERC1155_ID ^ bytes4(keccak256("uri(uint256)"));

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(bytes4 queryId) public {
        // General rule (universal over the whole bytes4 domain): the contract answers
        // supportsInterface(id) == true exactly for the interface ids of the standards it
        // implements: ERC165, IERC1155MetadataURI, and the base IERC1155 interface.
        bool expected =
            queryId == IERC1155_ID ||
            queryId == IERC1155_METADATA_URI_ID ||
            queryId == ERC165_ID;

        bool ok;
        try c.supportsInterface(queryId) returns (bool supported) {
            ok = supported;
        } catch {
            ok = false;
        }

        assertTrue(ok == expected, "supportsInterface must advertise exactly the implemented interfaces");
    }
}

