pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // the six selectors of IERC1155's public functions
    bytes4[6] selectors = [
        bytes4(keccak256("balanceOf(address,uint256)")),
        bytes4(keccak256("balanceOfBatch(address[],uint256[])")),
        bytes4(keccak256("setApprovalForAll(address,bool)")),
        bytes4(keccak256("isApprovedForAll(address,address)")),
        bytes4(keccak256("safeTransferFrom(address,address,uint256,uint256,bytes)")),
        bytes4(keccak256("safeBatchTransferFrom(address,address,uint256[],uint256[],bytes)"))
    ];

    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(uint256 idx) public {
        // pick one member function of the IERC1155 interface by fuzzed index
        uint256 i = bound(idx, 0, 5);
        // standard ERC-165 construction: interface id = XOR of all selectors except the chosen one
        bytes4 derived = 0;
        for (uint256 j = 0; j < 6; j++) {
            if (j != i) derived = derived ^ selectors[j];
        }
        assertTrue(c.supportsInterface(derived));
    }
}

