pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(uint256 selectorSeed) public {
        // Map a wide fuzzed domain onto admissible bytes4 inputs, including the
        // ERC-165 id, the ERC-1155 ids, and arbitrary non-standard ids.
        bytes4 erc165Id = type(IERC165).interfaceId;
        bytes4 erc1155Id = type(IERC1155).interfaceId;
        bytes4 erc1155MetaId = type(IERC1155MetadataURI).interfaceId;

        uint256 bucket = bound(selectorSeed, 0, 3);
        bytes4 id;
        if (bucket == 0) {
            id = erc165Id;
        } else if (bucket == 1) {
            id = erc1155Id;
        } else if (bucket == 2) {
            id = erc1155MetaId;
        } else {
            bytes4 raw = bytes4(uint32(selectorSeed));
            vm.assume(raw != erc165Id && raw != erc1155Id && raw != erc1155MetaId);
            id = raw;
        }

        bool ok = c.supportsInterface(id);

        // Rule: supportsInterface(id) == true exactly for the ERC-1155,
        // ERC-1155-MetadataURI and ERC-165 interface ids (ERC-165 inheritance
        // must report the IERC165 id), and false otherwise.
        assertTrue(
            ok == (id == erc1155Id || id == erc1155MetaId || id == erc165Id),
            "supportsInterface must honor the ERC-165 interface id via super"
        );
    }
}

